import React, { useRef } from 'react';
import emailjs from '@emailjs/browser';

function Formulario() {
  const form = useRef();

  const sendEmail = (e) => {
    e.preventDefault();

    emailjs
      .sendForm('service_x26zbd7', 'template_f70jm6p', form.current, {
        publicKey: 'EH-J2WJhCFQLeO',
      })
      .then(
        () => {
          console.log('SUCCESS!');
          alert('¡Solicitud de adopción/consulta enviada con éxito! Nos pondremos en contacto pronto.');
          form.current.reset();
        },
        (error) => {
          console.log('FAILED...', error.text);
          alert('Error al enviar el formulario. Por favor intenta nuevamente.');
        }
      );
  };

  return (
    <form ref={form} onSubmit={sendEmail} className="form-contacto">
      <h3>Formulario de Adopción y Contacto</h3>
      <div className="form-grupo">
        <label>Nombre Completo</label>
        <input type="text" name="username" placeholder="Tu nombre" required />
      </div>

      <div className="form-grupo">
        <label>Correo Electrónico</label>
        <input type="email" name="email" placeholder="tu@email.com" required />
      </div>

      <div className="form-grupo">
        <label>Mascota de Interés / Mensaje</label>
        <textarea name="message" rows="4" placeholder="Indica qué mascota deseas adoptar o tu consulta..." required />
      </div>

      <input type="submit" value="Enviar Solicitud" className="btn-submit" />
    </form>
  );
}

export default Formulario;
